#pragma once

#include <string_view>

#include "app_model/bounded_string.hpp"

// The provisioning setup access point — Architecture Spec §14.2, owner ruling R1.
//
// NO ESP-IDF HEADER APPEARS HERE (Bootstrap Spec §11.3), and none is needed: the session
// credential is generated by a pure translation unit the host suite compiles, and the
// driver adapter is separate.
//
// ⛔ MILESTONE 3.5 BRINGS UP AN ACCESS POINT AND NOTHING ELSE. There is no HTTP server, no
// captive portal, no mDNS, no DNS responder and no page of any kind — a client can
// associate and will find nothing listening. §14.4's server, its security set and its
// bounded idle lifetime arrive with the server itself at M3.7 (owner ruling D3: idle
// lifetime is meaningless while there are no requests to be idle between).
//
// ⚠️ THIS CHECKPOINT IS NOT INDEPENDENTLY USABLE, AND THAT IS DELIBERATE — owner ruling,
// 2026-08-15. The session password is generated per session, never persisted, and by owner
// ruling D1 it is NOT exposed over serial: no diagnostics flag, no debug path, nothing
// written to a log. Nobody can read it in M3.5, so nobody can join the access point. M3.6
// puts the SSID, the password and the local URL on the panel and completes the first
// human-usable slice. Do not add temporary observability to make this checkpoint usable on
// its own — it would be obsolete one checkpoint later.
//
// ⛔ WHY THE PASSWORD IS NOT IN AppState. §13.5 and §24.3: credentials never enter the
// application state, never reach a log and are never displayed except where the product
// deliberately shows them. Session lives in RAM, owned by app_core's boot sequence, and
// what reaches AppState is ProvisioningPhase and nothing more.

namespace prd::network::setup_ap {

// WPA2-PSK accepts 8-63 characters; §14.2 wants the password short-lived rather than long.
inline constexpr std::size_t kPasswordLength = 12;

// One provisioning session's access-point identity.
//
// GENERATED PER SESSION AND NEVER PERSISTED (R1). It opens no storage namespace, writes no
// NVS key and is not derived from device identity — the SSID carries a device suffix so a
// user can tell two devices apart, the password is drawn fresh from the hardware RNG every
// time provisioning is entered.
struct Session {
    // Non-secret: §7.4 already documents the network name as displayable, and §14.2
    // requires the setup SSID to be shown.
    app_model::BoundedString<32> ssid;

    // SECRET. This is the source session; start() wipes the driver's temporary
    // copy, and the app/UI handoff wipes its temporary copies after delivery.
    // The scene retains only the currently displayed session until retirement.
    app_model::BoundedString<63> password;

    // Overwrites the password rather than merely marking it empty.
    void clear();
};

// Generates a fresh session — a new password on every call, from the hardware RNG.
[[nodiscard]] Session new_session();

// Brings the access point up. Idempotent: a second call while running does nothing.
//
// Returns false when the driver could not be brought up or configured. The session's
// password is copied into the driver configuration and that copy is wiped before return;
// the caller's Session is not modified.
[[nodiscard]] bool start(const Session& session);

// Stops the access point. Idempotent.
void stop();

[[nodiscard]] bool running();

// The address the access point answers on, e.g. "192.168.4.1". Empty until it is up.
//
// Read from the interface rather than assumed: ESP-IDF's DHCP server chooses it, and a
// hard-coded default would be a second source of truth that could disagree with the one a
// client is actually handed. app_core passes this to the provisioning server, which is how
// `provisioning` serves on the right address without ever seeing esp_wifi (owner ruling D5).
[[nodiscard]] std::string_view address();

} // namespace prd::network::setup_ap
